-- kobe:hand-written
-- (db:rebase keeps this SQL and its snapshot and only renumbers it: never regenerate it.)
-- KOBE-668 (Gate B decision 13): readers' suggestions whose thread left the project go `stale`,
-- apart from `expired` (no decision within 30 days, the KOBE-651 sweep), and the suggester is told
-- with the new notification kind `memory.suggestion.stale`. Drizzle generated the CHECK statements;
-- the UPDATE after them is hand-written (it must run after the widened state CHECK).
--
-- Existing rows: before this, both paths wrote `expired` with `decided_at = now()` and no decider.
-- The sweep only touches rows with `expires_at <= now()`, so an `expired` row decided before its
-- `expires_at` can only have been staled: it becomes `stale`. A row staled after its `expires_at`
-- (thread moved before the nightly sweep reached it) is indistinguishable from a swept one and
-- stays `expired`. No audit event records either path. Notifications already sent keep their
-- kind (`memory.suggestion.expired`).
--
-- Migrations run as the owner role (no superuser, no BYPASSRLS) and the table has FORCE ROW LEVEL
-- SECURITY with no `kobe.team_id` set, so FORCE is lifted for the update only (one transaction;
-- ALTER TABLE holds its lock until commit), as 0201/0202. Only the state changes: no row is
-- deleted, so the legal-hold guards (DELETE/TRUNCATE) are not involved.
-- (memory-suggestion-stale-upgrade.db.test.ts migrates a populated database.)
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_kind";--> statement-breakpoint
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_actor";--> statement-breakpoint
ALTER TABLE "notifications" DROP CONSTRAINT "notifications_memory";--> statement-breakpoint
ALTER TABLE "memory_project_suggestions" DROP CONSTRAINT "memory_project_suggestions_state";--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_kind" CHECK ("notifications"."kind" IN ('schedule.run.succeeded', 'schedule.run.failed', 'schedule.run.interrupted', 'schedule.run.skipped_actions', 'schedule.paused', 'skill.member_add.blocked', 'skill.deprecated', 'skill.version.deprecated', 'skill.version.withdrawn', 'skill.version.revoked', 'skill.version.unrevoked', 'skill.version.site_published', 'team.member.added', 'team.site_admin.member_added', 'team.site_admin.member_role_changed', 'team.site_admin.member_removed', 'team.site_admin.member_taken_over', 'memory.scope.near_full', 'memory.review.reminder', 'memory.review.digest', 'memory.review.candidates_ready', 'memory.proposal.received', 'memory.proposal.accepted', 'memory.proposal.dismissed', 'memory.proposal.changes_requested', 'memory.proposal.expired', 'memory.suggestion.received', 'memory.suggestion.accepted', 'memory.suggestion.dismissed', 'memory.suggestion.expired', 'memory.suggestion.stale', 'memory.site_proposal.received', 'memory.site_proposal.confirmed', 'memory.site_proposal.changes_requested', 'memory.site_proposal.accepted', 'memory.site_proposal.dismissed', 'memory.site_proposal.expired'));--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_actor" CHECK (("notifications"."kind" = 'skill.version.site_published' OR "notifications"."kind" LIKE 'team.%') = ("notifications"."actor_user_id" IS NOT NULL)
        OR ("notifications"."kind" IN ('memory.proposal.received', 'memory.proposal.accepted', 'memory.proposal.dismissed', 'memory.proposal.changes_requested', 'memory.proposal.expired', 'memory.suggestion.received', 'memory.suggestion.accepted', 'memory.suggestion.dismissed', 'memory.suggestion.expired', 'memory.suggestion.stale', 'memory.site_proposal.received', 'memory.site_proposal.confirmed', 'memory.site_proposal.changes_requested', 'memory.site_proposal.accepted', 'memory.site_proposal.dismissed', 'memory.site_proposal.expired')));--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_memory" CHECK (COALESCE(("notifications"."kind" NOT LIKE 'memory.%' AND "notifications"."memory_scope" IS NULL AND "notifications"."memory_object_id" IS NULL AND "notifications"."related_kind" IS NULL AND "notifications"."item_count" IS NULL AND "notifications"."project_id" IS NULL)
        OR ("notifications"."kind" = 'memory.scope.near_full' AND "notifications"."memory_scope" IN ('team', 'site') AND "notifications"."memory_object_id" IS NULL AND "notifications"."related_kind" IS NULL AND "notifications"."item_count" IS NULL AND "notifications"."project_id" IS NULL AND "notifications"."actor_user_id" IS NULL)
        OR ("notifications"."kind" = 'memory.review.candidates_ready' AND "notifications"."thread_id" IS NOT NULL AND "notifications"."item_count" >= 1 AND "notifications"."memory_scope" IS NULL AND "notifications"."related_kind" IS NULL AND "notifications"."project_id" IS NULL AND "notifications"."actor_user_id" IS NULL)
        OR ("notifications"."kind" = 'memory.review.digest' AND "notifications"."related_kind" IN ('memory.scope.near_full', 'memory.review.reminder', 'memory.review.candidates_ready', 'memory.proposal.received', 'memory.proposal.accepted', 'memory.proposal.dismissed', 'memory.proposal.changes_requested', 'memory.proposal.expired', 'memory.suggestion.received', 'memory.suggestion.accepted', 'memory.suggestion.dismissed', 'memory.suggestion.expired', 'memory.suggestion.stale', 'memory.site_proposal.received', 'memory.site_proposal.confirmed', 'memory.site_proposal.changes_requested', 'memory.site_proposal.accepted', 'memory.site_proposal.dismissed', 'memory.site_proposal.expired') AND "notifications"."item_count" >= 1 AND "notifications"."memory_scope" IS NULL AND "notifications"."memory_object_id" IS NULL AND "notifications"."project_id" IS NULL AND "notifications"."actor_user_id" IS NULL)
        OR ("notifications"."kind" = 'memory.review.reminder' AND "notifications"."memory_object_id" IS NOT NULL AND ("notifications"."related_kind" IS NULL OR "notifications"."related_kind" IN ('memory.proposal.received', 'memory.suggestion.received', 'memory.site_proposal.received', 'memory.site_proposal.confirmed', 'memory.site_proposal.changes_requested')) AND ("notifications"."project_id" IS NOT NULL) = ("notifications"."related_kind" IS NOT DISTINCT FROM 'memory.suggestion.received') AND "notifications"."memory_scope" IS NULL AND "notifications"."item_count" IS NULL AND "notifications"."actor_user_id" IS NULL)
        OR ("notifications"."kind" IN ('memory.proposal.received', 'memory.proposal.accepted', 'memory.proposal.dismissed', 'memory.proposal.changes_requested', 'memory.proposal.expired', 'memory.suggestion.received', 'memory.suggestion.accepted', 'memory.suggestion.dismissed', 'memory.suggestion.expired', 'memory.suggestion.stale', 'memory.site_proposal.received', 'memory.site_proposal.confirmed', 'memory.site_proposal.changes_requested', 'memory.site_proposal.accepted', 'memory.site_proposal.dismissed', 'memory.site_proposal.expired') AND "notifications"."memory_object_id" IS NOT NULL AND ("notifications"."project_id" IS NOT NULL) = ("notifications"."kind" LIKE 'memory.suggestion.%') AND "notifications"."memory_scope" IS NULL AND "notifications"."related_kind" IS NULL AND "notifications"."item_count" IS NULL), false));--> statement-breakpoint
ALTER TABLE "memory_project_suggestions" ADD CONSTRAINT "memory_project_suggestions_state" CHECK ("memory_project_suggestions"."state" IN ('pending', 'approved', 'dismissed', 'expired', 'stale'));--> statement-breakpoint
ALTER TABLE "memory_project_suggestions" NO FORCE ROW LEVEL SECURITY;--> statement-breakpoint
UPDATE "memory_project_suggestions" SET "state" = 'stale'
 WHERE "state" = 'expired' AND "decided_at" < "expires_at";--> statement-breakpoint
ALTER TABLE "memory_project_suggestions" FORCE ROW LEVEL SECURITY;
